       await this.ensureClient(config);
       const session = await this.getOrCreateSession(config, workingDir);
       ephemeralSession = session.ephemeralSession;

       const promptOptions = this.buildPromptParameters(
         config,
         prompt,
         session.sessionId,
         session.sessionQuery,
       );

